package com.example.approval.domain;
import java.math.BigDecimal; import java.util.Currency;
public record Money(BigDecimal amount, Currency currency) { public Money { if(amount==null || currency==null) throw new InvalidMonetaryValueException("Amount and currency are required"); if(amount.signum()<=0) throw new InvalidMonetaryValueException("Amount must be positive"); if(amount.scale()>currency.getDefaultFractionDigits()) throw new InvalidMonetaryValueException("Too many fractional digits for "+currency.getCurrencyCode()); amount=amount.setScale(currency.getDefaultFractionDigits()); } public static Money of(String amount,String currency){try{return new Money(new BigDecimal(amount),Currency.getInstance(currency));}catch(RuntimeException e){if(e instanceof InvalidMonetaryValueException m) throw m; throw new InvalidMonetaryValueException("Invalid amount or currency",e);}} }